templates.react:
export function TourStep({
  title = "{{title}}",
  body = "{{body}}",
  step = {{step}},
  total = {{total}},
  placement = "{{placement}}",
  accent = "{{accent}}",
}) {
  const pos = {
    top: { left: "50%", bottom: "calc(50% + 60px)", transform: "translateX(-50%)" },
    bottom: { left: "50%", top: "calc(50% + 60px)", transform: "translateX(-50%)" },
    left: { right: "calc(50% + 60px)", top: "50%", transform: "translateY(-50%)" },
    right: { left: "calc(50% + 60px)", top: "50%", transform: "translateY(-50%)" },
  }[placement] ?? {};
  return (
    <div style={{ position: "relative", fontFamily: "system-ui, sans-serif", color: "#241430", width: 360, height: 240, background: "#FAF7F2", borderRadius: 14, border: "1px solid #24143018" }}>
      <div aria-hidden="true" style={{ position: "absolute", top: "50%", left: "50%", transform: "translate(-50%,-50%)", width: 64, height: 64, borderRadius: 999, background: "#fff", boxShadow: "0 0 0 6px #24143010", display: "flex", alignItems: "center", justifyContent: "center" }}>
        <span style={{ width: 16, height: 16, borderRadius: 999, background: accent }} />
      </div>
      <div style={{ position: "absolute", width: 200, background: "#fff", borderRadius: 10, padding: "14px 16px", boxShadow: "0 10px 26px rgba(36,20,48,.2)", ...pos }}>
        <button type="button" aria-label="Close tour" style={{ position: "absolute", top: 6, right: 6, width: 20, height: 20, border: "none", background: "transparent", color: "#24143070", fontSize: 13, borderRadius: 5, cursor: "pointer" }}>×</button>
        <p style={{ margin: "0 0 4px", fontSize: 10.5, fontWeight: 700, color: accent, textTransform: "uppercase", letterSpacing: ".04em" }}>Step {step} of {total}</p>
        <h4 style={{ margin: "0 0 4px", fontSize: 14, fontWeight: 700 }}>{title}</h4>
        <p style={{ margin: "0 0 10px", fontSize: 12, color: "#241430b3" }}>{body}</p>
        <div style={{ display: "flex", justifyContent: "flex-end" }}>
          <button type="button" style={{ background: accent, border: "1.5px solid " + accent, borderRadius: 7, padding: "5px 11px", fontSize: 12, fontWeight: 600, cursor: "pointer" }}>Next</button>
        </div>
      </div>
    </div>
  );
}
